@props(['assessment', 'revised' => false])
<section class="checker-organised-report" aria-label="Job requirements and recommendations">
    @if(!empty($assessment['suggestions']))<details class="checker-report-disclosure"><summary>Suggestions to improve your CV</summary><ul>@foreach($assessment['suggestions'] as $tip)<li><strong>{{ $tip['section'] }}</strong><p>{{ $tip['improvement'] }}</p><p>{{ $tip['reason'] }}</p></li>@endforeach</ul></details>@endif
    @if(!empty($assessment['recommendations']))<details class="checker-report-disclosure"><summary>Recommendations</summary><ul>@foreach($assessment['recommendations'] as $tip)<li>{{ $tip }}</li>@endforeach</ul></details>@endif
    @if(!empty($assessment['warnings']))<details class="checker-report-disclosure checker-report-warning" @if($revised) open @endif><summary>{{ $revised ? 'Remaining Warnings' : 'Warnings' }}</summary><div class="checker-report-warning-content"><ul>@foreach($assessment['warnings'] as $warning)<li><strong>{{ $warning['requirement'] }}</strong><p>{{ $warning['explanation'] }}</p><p>{{ $warning['recommended_action'] }}</p></li>@endforeach</ul></div></details>@endif
    @if(!empty($assessment['questions_for_candidate']))<details class="checker-report-disclosure"><summary>Information to confirm</summary><ul>@foreach($assessment['questions_for_candidate'] as $question)<li>{{ $question }}</li>@endforeach</ul></details>@endif
</section>
